import{g as a,ae as n,r as p,B as e}from"./chunks/framework.CZ-ntRvv.js";const h=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md","lastUpdated":1790191713000}'),t={name:"docs/getting-started.md"};function l(c,s,i,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Set up frappe-ui in a Vite and Vue 3 app. You need Node 20.19 or later.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick start”">​</a></h2><p>Create a new app with one command:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> create</span><span class="s_2575z4"> frappe-ui@latest</span></span></code></pre></div><p>It asks where to create the project and what it is for, then sets up Vue 3, TypeScript, Vite, Tailwind CSS and frappe-ui with a starter page.</p><ul><li><strong>Frontend of a Frappe app:</strong> run it from your app&#39;s folder, such as <code>apps/todo</code>. It creates <code>frontend/</code> and connects it to the app: the page that serves it, the route rule in <code>hooks.py</code>, the build scripts and <code>.gitignore</code>. It lists these changes and asks before it writes them.</li><li><strong>Standalone app:</strong> run it anywhere else for a plain Vite app with no Frappe server.</li></ul><p>When it finishes, it prints the next steps, including the command that starts the dev server.</p><h2 id="set-up-by-hand" tabindex="-1">Set up by hand <a class="header-anchor" href="#set-up-by-hand" aria-label="Permalink to “Set up by hand”">​</a></h2><p>Use these steps to add frappe-ui to an existing project, or to see what the command above sets up. The steps are the same with or without a Frappe server behind the app. Only the Vite config differs.</p><div class="steps"><h3 id="create-your-project" tabindex="-1">Create your project <a class="header-anchor" href="#create-your-project" aria-label="Permalink to “Create your project”">​</a></h3><p>Start with a Vue and TypeScript project from Vite. Skip this step if you already have one.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> create</span><span class="s_2575z4"> vite@latest</span><span class="s_2575z4"> my-app</span><span class="s_2d41qv"> --</span><span class="s_2d41qv"> --template</span><span class="s_2575z4"> vue-ts</span></span>
<span class="line"><span class="s_i592pt">cd</span><span class="s_2575z4"> my-app</span></span></code></pre></div><p>Building the frontend of a Frappe app? Create the project inside your app instead, as the <a href="./getting-started/frappe#create-the-frontend">Frappe app</a> guide shows.</p><h3 id="install-frappe-ui" tabindex="-1">Install frappe-ui <a class="header-anchor" href="#install-frappe-ui" aria-label="Permalink to “Install frappe-ui”">​</a></h3><p>Install Tailwind CSS v3, frappe-ui and Vue Router. frappe-ui doesn&#39;t support Tailwind CSS v4 yet.</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> install</span><span class="s_2d41qv"> -D</span><span class="s_2575z4"> tailwindcss@^3.4</span><span class="s_2575z4"> postcss</span><span class="s_2575z4"> autoprefixer</span></span>
<span class="line"><span class="s_euu481">npm</span><span class="s_2575z4"> install</span><span class="s_2575z4"> frappe-ui</span><span class="s_2575z4"> vue-router</span></span></code></pre></div><h3 id="configure-tailwind-css" tabindex="-1">Configure Tailwind CSS <a class="header-anchor" href="#configure-tailwind-css" aria-label="Permalink to “Configure Tailwind CSS”">​</a></h3><p>Add the frappe-ui preset to <code>tailwind.config.js</code>, and include frappe-ui&#39;s <code>content</code> paths so its classes get generated.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> preset</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">/** </span><span class="s_y1rh3e">@type</span><span class="s_1zp9pn"> {</span><span class="s_1b1qqa">import(&#39;tailwindcss&#39;).Config</span><span class="s_1zp9pn">}</span><span class="s_1th9sy"> */</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  presets</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_11933w">preset</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./index.html</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>Then turn Tailwind on in <code>postcss.config.js</code>.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  plugins</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> tailwindcss</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {}</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> autoprefixer</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {}</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h3 id="import-the-styles" tabindex="-1">Import the styles <a class="header-anchor" href="#import-the-styles" aria-label="Permalink to “Import the styles”">​</a></h3><p>Replace everything in <code>src/style.css</code> with one import. It brings in Tailwind and the Inter font, so don&#39;t add the <code>@tailwind</code> lines yourself.</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span></code></pre></div><h3 id="add-the-provider" tabindex="-1">Add the provider <a class="header-anchor" href="#add-the-provider" aria-label="Permalink to “Add the provider”">​</a></h3><p>Wrap your app in <code>FrappeUIProvider</code> in <code>src/App.vue</code>. It renders dialogs and toasts opened from code.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1i4ay4"> lang</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeUIProvider</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">FrappeUIProvider</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">RouterView</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">FrappeUIProvider</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Then add a router and the styles in <code>src/main.ts</code>. Some components link to routes, so frappe-ui needs Vue Router even in a one-page app.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createApp</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createRouter</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> createWebHistory</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue-router</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> App</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./App.vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> Home</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./pages/Home.vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./style.css</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> router</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createRouter</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  history</span><span class="s_1jjt6x">:</span><span class="s_indoxt"> createWebHistory</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  routes</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> path</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> component</span><span class="s_1jjt6x">:</span><span class="s_11933w"> Home</span><span class="s_13ahmt"> }]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">createApp</span><span class="s_13ahmt">(</span><span class="s_22m8k2">App</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">router</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">mount</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">#app</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span></code></pre></div><h3 id="configure-vite" tabindex="-1">Configure Vite <a class="header-anchor" href="#configure-vite" aria-label="Permalink to “Configure Vite”">​</a></h3><p><code>vite.config.ts</code> depends on where the app runs. Follow the guide that fits:</p><ul><li><a href="./getting-started/frappe#add-the-vite-plugin">Frappe app</a>: adds the frappe-ui Vite plugin, which proxies your bench and builds into the app.</li><li><a href="./getting-started/standalone#vite-config">Standalone app</a>: adds the same plugin with its Frappe server features turned off.</li></ul><h3 id="start-using-frappe-ui" tabindex="-1">Start using frappe-ui <a class="header-anchor" href="#start-using-frappe-ui" aria-label="Permalink to “Start using frappe-ui”">​</a></h3><p>Put a component in <code>src/pages/Home.vue</code> and run <code>npm run dev</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1i4ay4"> lang</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Button</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> variant</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">solid</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> icon-left</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">New task</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>You should see a dark button with a plus icon, in the Inter font. If the icon is an empty square, Tailwind isn&#39;t reading frappe-ui&#39;s files. Check the <code>content</code> line in <code>tailwind.config.js</code>.</p></div><h2 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to “TypeScript”">​</a></h2><p>Extend frappe-ui&#39;s base config in <code>tsconfig.json</code>.</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">extends</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">frappe-ui/tsconfig.base.json</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">compilerOptions</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_1xnzz2">    &quot;</span><span class="s_i592pt">types</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">vite/client</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1xnzz2">  &quot;</span><span class="s_230ye1">include</span><span class="s_1xnzz2">&quot;</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">src/**/*.ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &quot;</span><span class="s_2575z4">src/**/*.vue</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>Keep <code>vite/client</code> in <code>types</code>. frappe-ui ships its TypeScript source, and that source reads <code>import.meta.env</code>.</p><p>Import types from the same place as the component:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Button</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> ButtonProps</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">Editor</span><span class="s_1jjt6x">,</span><span class="s_50ecpt"> type</span><span class="s_4q1z3w"> RichTextKitOptions</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><h2 id="entry-points" tabindex="-1">Entry points <a class="header-anchor" href="#entry-points" aria-label="Permalink to “Entry points”">​</a></h2><p>Import only from the paths frappe-ui exports. Deeper paths such as <code>frappe-ui/src/...</code> fail with <code>Package subpath is not defined</code>.</p><table tabindex="0"><thead><tr><th>Path</th><th>What it has</th></tr></thead><tbody><tr><td><code>frappe-ui</code></td><td>Components, composables and data fetching</td></tr><tr><td><code>frappe-ui/list</code></td><td>The list components</td></tr><tr><td><code>frappe-ui/editor</code></td><td>The rich text editor</td></tr><tr><td><code>frappe-ui/code-editor</code></td><td>The code editor</td></tr><tr><td><code>frappe-ui/charts</code></td><td>Charts</td></tr><tr><td><code>frappe-ui/icons</code></td><td>Frappe&#39;s own icon components</td></tr><tr><td><code>frappe-ui/experimental</code></td><td>Components whose API may still change</td></tr><tr><td><code>frappe-ui/tailwind</code></td><td>The Tailwind preset and <code>content</code> paths</td></tr><tr><td><code>frappe-ui/tailwind/tokens</code></td><td>The design tokens as plain data</td></tr><tr><td><code>frappe-ui/vite</code></td><td>The Vite plugin</td></tr><tr><td><code>frappe-ui/vite/lucideIconsPlugin</code></td><td>Only the <code>~icons/lucide/*</code> resolver from the Vite plugin</td></tr><tr><td><code>frappe-ui/style.css</code></td><td>The base stylesheet</td></tr><tr><td><code>frappe-ui/tsconfig.base.json</code></td><td>The base TypeScript config</td></tr><tr><td><code>frappe-ui/vitepress</code></td><td>The theme for frappe-ui&#39;s own docs. Don&#39;t import it in apps.</td></tr></tbody></table>`,20)])])}const u=a(t,[["render",l]]);export{h as __pageData,u as default};
